static u8 cliff_block(u8 id, u8 part) {
    const u8 *m = cliff_meta + (u16)id * 5;
    u8 w = m[3], h = m[4];
    u8 r0 = (u8)(part * 4), r1 = (u8)(r0 + 4);
    const u8 *t, *a;
    if (r1 > h) r1 = h;
    t = cliff_bt[id] + (u16)r0 * w;
    a = cliff_ba[id] + (u16)r0 * w;
    if (m[0]) {
        set_win_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), t);
        VBK_REG = 1;
        set_win_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), a);
    } else {
        set_bkg_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), t);
        VBK_REG = 1;
        set_bkg_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), a);
    }
    VBK_REG = 0;
    return r1 < h ? 1 : 0;
}

u8 intro_io_cliff(u8 op, u8 a, u8 b) BANKED {
    switch (op) {
    case IOP_LOAD:
        if (a < 11u) {
            u16 first = (u16)a << 5;
            u8 cnt = (335u - first) > 32 ? 32 : (u8)(335u - first);
            VBK_REG = (u8)(first >> 8);
            set_bkg_data((u8)first, cnt, cliff_tiles + (first << 4));
            VBK_REG = 0;
            return 1;
        }
        if ((u8)(a - 11u) < 4u) {
            cliff_block(0, (u8)(a - 11u));
            return 1;
        }
        memcpy(intro_pal, cliff_pals, 64);
        return 0;
    case IOP_BLOCK:
        return cliff_block(a, b);
    case IOP_PAL:
        memcpy(intro_pal, cliff_pals + (u16)a * 32, 64);
        return 0;
    }
    return 0;
}
